head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil00020";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — mainnumber, tempSaveYn

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_ctxDefaults();
        scwin.init_fillGen();
        scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil00020.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "txa_tempdisclsDocTxtfile", attr: "label", fn: function () { return String(dma_disclosureVo.get("disclsDocTxtfile")); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_ctxDefaults
 * @description 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다. 진입 기본값 충전 — 파라미터로 안 온 키에 스펙 기본값(조건 평가보다 먼저).
 * @returns {void}
 * @hidden N
 */
scwin.init_ctxDefaults = function () {
    const cds = {"mainnumber":"0"};
    const pc0 = $c.util.getComponent("dma_pageContext");
    if (!pc0 || !pc0.get || !pc0.set) { return; }
    for (let ck in cds) { const cv0 = pc0.get(ck); if (cv0 === undefined || cv0 === null || cv0 === '') { pc0.set(ck, cds[ck]); } }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_wrtrptMaindocTpCd", fn: function(){ return ((dlt_disclosureContentVoArr.getCellData(0, "wrtrptMaindocTpCd") ?? (() => { throw new Error("unresolved:" + "doc.wrtrptMaindocTpCd"); })()) === '1'); } }, { id: "tr_84", fn: function(){ return ((dlt_disclosureContentVoArr.getCellData(0, "wrtrptMaindocTpCd") ?? (() => { throw new Error("unresolved:" + "doc.wrtrptMaindocTpCd"); })()) === '1'); } }, { id: "if_mainnumber", fn: function(){ return ((dma_pageContext.get("mainnumber") ?? "") === 0); } }, { id: "tr_88", fn: function(){ return ((dma_pageContext.get("mainnumber") ?? "") === 0); } }, { id: "if_wrtrptMaindocTpCd_2", fn: function(){ return ((dlt_disclosureContentVoArr.getCellData(0, "wrtrptMaindocTpCd") ?? (() => { throw new Error("unresolved:" + "doc.wrtrptMaindocTpCd"); })()) === '2'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_80", entity: "dlt_disclosureContentVoArr", countIds: [], cells: [{ childId: "__rc3", fn: function (v, i) { return String(v("documentHtml")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb4", fn: function () { return dlt_disclosureContentVoArr.getCellData(0, "documentHtml"); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

// [A] 초기 목록 미해결 — jldfil00020: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_checkLang_onchange
 * @description slc_checkLang 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_checkLang_onchange = async function(e){
    try {
        await scwin.goPrint()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00020.slc_checkLang_onchange' }); }
};

/**
 * @method
 * @name ipt_cominfochk_onclick
 * @description ipt_cominfochk 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_cominfochk_onclick = function(e){
    try {
        scwin.check(1)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00020.ipt_cominfochk_onclick' }); }
};

/**
 * @method
 * @name ipt_attachchk_onclick
 * @description ipt_attachchk 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_attachchk_onclick = function(e){
    try {
        scwin.check(2)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00020.ipt_attachchk_onclick' }); }
};

/**
 * @method
 * @name ipt_cautchk_onclick
 * @description ipt_cautchk 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_cautchk_onclick = function(e){
    try {
        scwin.check(3)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00020.ipt_cautchk_onclick' }); }
};

/**
 * @method
 * @name img_48_onclick
 * @description img_48 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_48_onclick = async function(e){
    try {
        await scwin.print()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00020.img_48_onclick' }); }
};

/**
 * @method
 * @name img_50_onclick
 * @description img_50 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_50_onclick = async function(e){
    try {
        await scwin.excel()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00020.img_50_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_excel
 * @description excel 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_excel = async function () {
    try { return await $c.data.downFile("/submission/disclosure.do?method=searchDocumentPrintExcel", "", ($c.util.getComponent("dma_excelReq") ? $c.util.getComponent("dma_excelReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name tx_fn_goPrint
 * @description go Print 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goPrint = async function () {
    try { return await $c.data.downFile("/submission/disclosure.do?method=searchDocumentPrint", "", ($c.util.getComponent("dma_goPrintReq") ? $c.util.getComponent("dma_goPrintReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name print
 * @description print 처리
 * @returns {void}
 * @hidden N
 */
scwin.print = async function () {
    await $c.win.print();
};

/**
 * @method
 * @name close
 * @description close 처리
 * @returns {void}
 * @hidden N
 */
scwin.close = function () {
    /* empty */
};

/**
 * @method
 * @name check
 * @description check 처리
 * @param {*} div div
 * @returns {void}
 * @hidden N
 */
scwin.check = function (div) {
    if (div === '1') {
        if ($c.util.getComponent("cominfo")) {
            if ($c.util.getComponent("cominfo").getStyle("display") === 'block') {
                $c.util.getComponent("cominfo").setStyle("display", 'none');
            } else {
                $c.util.getComponent("cominfo").setStyle("display", 'block');
            }
        }
    } else {
        if (div === '2') {
            if (document.all('attach')) {
                if (document.all('attach').style.display === 'block') {
                    document.all('attach').style.display = 'none';
                } else {
                    document.all('attach').style.display = 'block';
                }
            }
        } else {
            if (div === '3') {
                if ($c.util.getComponent("caut")) {
                    if ($c.util.getComponent("caut").getStyle("display") === 'block') {
                        $c.util.getComponent("caut").setStyle("display", 'none');
                    } else {
                        $c.util.getComponent("caut").setStyle("display", 'block');
                    }
                }
            }
        }
    }
};

/**
 * @method
 * @name excel
 * @description excel 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excel = async function () {
    let documentHtml = '';
    if ($c.util.getComponent("cominfo")) {
        if ($c.util.getComponent("cominfo").getStyle("display") === 'block') {
            $c.util.getComponent("cominfo_img").innerHTML = '';
            documentHtml = documentHtml + $c.util.getComponent("cominfo").innerHTML;
            $c.util.getComponent("cominfo_img").innerHTML = '<img  src="/img/submission/main/print_1.gif">';
        }
    }
    if ($c.util.getComponent("maindoc")) {
        if ($c.util.getComponent("maindoc").getStyle("display") === 'block') {
            documentHtml = documentHtml + $c.util.getComponent("maindoc").innerHTML;
        }
    }
    if (document.all('attach')) {
        if (document.all("attach").style.display === 'block') {
            documentHtml = documentHtml + document.all("attach").innerHTML;
        }
    }
    if ($c.util.getComponent("caut")) {
        if ($c.util.getComponent("caut").getStyle("display") === 'block') {
            $c.util.getComponent("caut_img").innerHTML = '';
            documentHtml = documentHtml + $c.util.getComponent("caut").innerHTML;
            $c.util.getComponent("caut_img").innerHTML = '<img src="/img/submission/main/print_2.gif">';
        }
    }
    $c.util.getComponent('dma_excelReq').set('documentHtml', documentHtml);
    (document.submitFrm || { elements: [] }).action = 'disclosure.do?method=searchDocumentPrintExcel';
    await scwin.tx_fn_excel();
};

/**
 * @method
 * @name goPrint
 * @description go Print 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goPrint = async function () {
    const langSelect = $c.util.getComponent('slc_checkLang').getValue();
    if ((String(((dma_pageContext.get("tempSaveYn") ?? "")) == null ? '' : ((dma_pageContext.get("tempSaveYn") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("tempSaveYn") ?? "")) == null ? '' : ((dma_pageContext.get("tempSaveYn") ?? "")))) !== 'Y') {
        await $c.win.alert('임시저장된 문서에 대해서 만 사용하실 수 있습니다');
        return;
    }
    $c.util.getComponent('dma_excelReq').set('langTpCd', langSelect);
    $c.util.getComponent('dma_excelReq').set('disclsDocTxtfile', $c.util.getComponent('txa_tempdisclsDocTxtfile').getValue());
    (document.printFrm || { elements: [] }).action = 'disclosure.do?method=searchDocumentPrint';
    await scwin.tx_fn_goPrint();
};
